function readHistory(): { items: TournamentData[]; blocked: boolean } {
  try {
    const text = localStorage.getItem(KEY);
    if (!text) return { items: [], blocked: false };
    const data: unknown = JSON.parse(text);
    if (
      !data ||
      typeof data !== 'object' ||
      Array.isArray(data) ||
      Object.keys(data).sort().join(',') !== 'items,v'
    )
      return { items: [], blocked: false };
    const envelope = data as { v: unknown; items: unknown };
    if (envelope.v !== 3 || !Array.isArray(envelope.items) || envelope.items.length > 10)
      return { items: [], blocked: false };
    const items: TournamentData[] = [];
    for (const item of envelope.items) {
      const decoded = decodeTournament(
        JSON.stringify({
          format: 'neon-pairs/tournament',
          version: 1,
          tournament: item,
          count: 4,
          drafts: Array(8).fill(''),
        }),
      );
      if (
        typeof decoded === 'string' ||
        !decoded.tournament ||
        decoded.tournament.phase !== 'complete'
