    if (
      value.format !== 'neon-pairs/tournament' ||
      value.version !== 1 ||
      (value.count !== 4 && value.count !== 8) ||
      !Array.isArray(value.drafts) ||
      value.drafts.length !== 8 ||
      value.drafts.some((x: unknown) => typeof x !== 'string' || x.length > 1000)
