    if (extra) return `Unknown field: ${extra}.`;
    if (
      !Array.isArray(t.names) ||
      (t.names.length !== 4 && t.names.length !== 8) ||
      t.names.some((x: unknown) => typeof x !== 'string' || normalizeName(x) !== x) ||
      nameError(t.names as string[]) ||
