      const game = decodeSnapshot(t.snapshot as string);
      if (!game || game.boardCode !== last.code || game.matched.length === game.deck.length)
        return 'Invalid tournament.';
    }
    return {
      tournament: { names, matches, phase, snapshot: t.snapshot as string | null },
      drafts,
      count: value.count,
    };
  } catch {
    return 'Invalid tournament.';
  }
}

