import { Playing } from './Playing.tsx';
import type { PlayHandle } from './Playing.tsx';
import { Bracket } from './Bracket.tsx';
import { newMatch, roundName } from './rules.ts';
import { nextCode } from './history.ts';
import type { Match, Result, TournamentState } from './rules.ts';
import type { Dispatch, RefObject, SetStateAction } from 'react';

interface Props {
  t: TournamentState;
  last: Match;
  player: number;
  playKey: number;
  setPlayKey: Dispatch<SetStateAction<number>>;
  setT(t: TournamentState): void;
  play: RefObject<PlayHandle | null>;
  completeTurn(result: Result): void;
  back(): void;
  leave(): void;
}
export function Active({
  t,
  last,
  player,
  playKey,
  setPlayKey,
  setT,
  play,
  completeTurn,
  back,
  leave,
}: Props) {
  return (
    <>
      <p>Round: {roundName(t.names.length, t.matches.length - 1)}</p>
      {t.phase === 'complete' ? (
        <p className="champion">Champion: {t.names[last.winner!]}</p>
      ) : (
        <p>Now playing: {t.names[player]}</p>
      )}
      {t.phase === 'ready' && (
        <button
          className="control"
          type="button"
          onClick={() => {
            setPlayKey((key) => key + 1);
            setT({ ...t, phase: 'playing', snapshot: null });
          }}
        >
          Start turn
        </button>
      )}
      {t.phase === 'playing' && (
        <Playing
          key={playKey}
          code={last.code}
          snapshot={t.snapshot}
          finished={completeTurn}
          handle={play}
        />
      )}
      {t.phase === 'turnDone' && (
        <button className="control" type="button" onClick={() => setT({ ...t, phase: 'ready' })}>
          Next turn
        </button>
      )}
      {t.phase === 'matchDone' && (
        <button
          className="control"
          type="button"
          onClick={() =>
            setT({
              ...t,
              matches: [...t.matches, newMatch(t.names, t.matches, nextCode(t))],
              phase: 'ready',
            })
          }
        >
          Next match
        </button>
      )}
      <p role="status" aria-live="polite" aria-atomic="true">
        {t.phase === 'turnDone'
          ? `${t.names[last.players[0]]} finished in ${last.results[0]?.moves} moves.`
          : t.phase === 'matchDone'
            ? `${t.names[last.winner!]} wins the match.`
            : t.phase === 'complete'
              ? `${t.names[last.winner!]} wins the tournament.`
              : ''}
      </p>
      <Bracket t={t} />
      {t.phase === 'complete' ? (
        <button className="control" type="button" onClick={back}>
          Back to game
        </button>
      ) : (
        <button
          className="control"
          type="button"
          onClick={() => {
            leave();
          }}
        >
          Leave tournament
        </button>
      )}
    </>
  );
}
import { useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { encodeProgress, decodeProgress } from './progress.ts';
import { activateSession, initialSession } from '../session/session.ts';
import type { Session } from '../session/session.ts';
import { useSessionClock } from '../session/use-session-clock.ts';
import type { Result } from './rules.ts';

export interface PlayHandle {
  snapshot(): string;
}
export function Playing({
  code,
  snapshot,
  finished,
  handle,
}: {
  code: string;
  snapshot: string | null;
  finished(result: Result): void;
  handle: React.RefObject<PlayHandle | null>;
}) {
  const [session, setSession] = useState(() => {
    const initial = initialSession(code, { size: 4, bestMoves: {} });
    const game = snapshot ? decodeProgress(snapshot) : null;
    return game ? { ...initial, game, paused: true } : initial;
  });
  const current = useRef<Session>(session);
  const board = useRef<BoardFocus>(null);
  function commit(next: Session) {
    current.current = next;
    setSession(next);
  }
  const clock = useSessionClock(session, current, commit);
  handle.current = {
    snapshot: () => {
      clock.synchronize();
      return encodeProgress(current.current.game);
    },
  };
  function activate(index: number) {
    clock.synchronize();
    const next = activateSession(current.current, index);
    // This session is isolated and never writes its temporary preferences.
    commit(next);
    if (!isWon(current.current.game)) return;
    finished({ moves: next.game.moves, elapsedMs: next.game.elapsedMs });
  }
  return (
    <>
      <dl className="stats">
        <div>
          <dt>Moves</dt>
          <dd>{session.game.moves}</dd>
        </div>
        <div>
          <dt>Pairs</dt>
          <dd>
            {session.game.matched.length / 2}/{session.game.deck.length / 2}
          </dd>
        </div>
        <div>
          <dt>Time</dt>
          <dd>{formatElapsed(session.game.elapsedMs)}</dd>
        </div>
      </dl>
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={session.announcement}>{session.feedback}</span>
        </p>
      </div>
      {session.paused && (
        <button
          className="control"
          type="button"
          onClick={() => {
            clock.reset();
            commit({ ...current.current, paused: false });
            board.current?.focusRemembered();
          }}
        >
          Resume
        </button>
      )}
      <Board game={session.game} activate={activate} ref={board} />
    </>
  );
}

